messages.content:
A `deps.edn` file configures dependencies, paths, and aliases:

```clojure
{;; Source paths
 :paths ["src" "resources"]

 ;; Main dependencies
 :deps {org.clojure/clojure {:mvn/version "1.11.1"}
        ;; Maven coordinates
        metosin/malli {:mvn/version "0.13.0"}
        ;; Git dependency
        io.github.user/lib {:git/sha "abc123"}
        ;; Local jar
        my/lib {:local/root "libs/mylib.jar"}
        ;; Local project
        local/project {:local/root "../other-project"}}

 ;; Aliases for different scenarios
 :aliases
 {;; Development dependencies
  :dev {:extra-paths ["dev" "test"]
        :extra-deps {nrepl/nrepl {:mvn/version "1.0.0"}
                     cider/cider-nrepl {:mvn/version "0.30.0"}}}

  ;; Run tests
  :test {:extra-paths ["test"]
         :extra-deps {io.github.cognitect-labs/test-runner
                      {:git/tag "v0.5.1" :git/sha "dfb30dd"}}
         :main-opts ["-m" "cognitect.test-runner"]}

  ;; Build uberjar
  :build {:deps {io.github.clojure/tools.build
                 {:git/tag "v0.9.4" :git/sha "76b78fe"}}
          :ns-default build}

  ;; Run main function
  :run {:main-opts ["-m" "myapp.core"]}

  ;; REPL with extra tools
  :repl {:jvm-opts ["-Djdk.attach.allowAttachSelf"]
         :extra-deps {vlaaad/reveal {:mvn/version "1.3.280"}}
         :main-opts ["-m" "nrepl.cmdline"
                     "--middleware" "[cider.nrepl/cider-middleware]"]}}}
```

**Usage:**
```bash
clj                       # Start REPL
clj -M:dev               # REPL with dev deps
clj -M:test              # Run tests
clj -T:build uber        # Build uberjar
clj -M:run               # Run main
clj -M:dev:test          # Combine aliases
```
